Import re
Import pandas as pd

# Extract Chinese, English, letters, and numbers from a sentence
def remove_p(txt):
 txt1 = str(txt)
 if txt1.strip() == '':
 return ''
 rule = re.compile('[^a-zA-Z0-9\u4E00-\u9FA5]')
 txt2 = rule.sub('',txt1)
 return txt2

